/**
 * The AI-instruction FILE SET written into a scaffolded VS Code workspace.
 *
 * SOURCE: the generated tree `ai/` at the extension root, mirrored from the authority
 * `paracore/ai/` (its `shared/` plus `vscode/` halves) by
 * `paracore/scripts/gen-ai-workspace.py`. The mirrored tree is gated — a `--check` run fails if
 * it drifts from the authority.
 *
 * ⚠⚠ WHY THIS IS A TREE AND NOT ONE STRING. This module used to export a single string for a
 * single `.github/copilot-instructions.md`, and it was **generated by
 * `rap-server/server/sync_protos.py`** from the DOCSTRING of a Python module. Since that module
 * has a docstring, the generator exported the module's own *description* as the VS Code guide —
 * so the scaffolded workspace shipped a stub with no rules in it — and it **overwrote this file**
 * on every run, silently reverting any fix made here.
 *
 * Both failure modes are gone:
 *   * the content is a generated tree, kept in step by a gate rather than by hand;
 *   * this file is hand-written source, and `sync_protos.py` no longer writes it.
 *
 * The emitted layout (all four locations are VS Code defaults — no settings required):
 *
 *   .github/copilot-instructions.md          always loaded   (the router)
 *   .github/instructions/*.instructions.md   auto-applied    (`applyTo` frontmatter)
 *   .github/skills/<name>/SKILL.md           on activation   (progressive disclosure)
 *   .github/skills/<name>/references/*.md    on demand       (the complete API reference)
 */

import * as fs from "fs";
import * as path from "path";

/**
 * Files a scaffolded workspace must have. If any is absent the tree is stale or was never
 * bundled, and we fall through rather than emit a half-workspace.
 */
const REQUIRED = [
  "copilot-instructions.md",
  "instructions/scripts.instructions.md",
  "skills/paracore-engine/SKILL.md",
  "skills/paracore-engine/references/EXTENSION_METHODS.md",
];

/** Candidate locations of the tree, relative to the compiled bundle. */
function treeCandidates(): string[] {
  return [
    // dist/extension.js  → extension root   (packaged / webpack build)
    path.join(__dirname, "..", "ai"),
    // out/src/…          → extension root   (tsc test build)
    path.join(__dirname, "..", "..", "ai"),
  ];
}

function walk(dir: string, root: string, out: Record<string, string>): void {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const abs = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(abs, root, out);
    } else if (entry.isFile()) {
      // posix-relative, so the paths are identical on every platform
      out[path.relative(root, abs).split(path.sep).join("/")] = fs.readFileSync(abs, "utf-8");
    }
  }
}

function loadTree(): Record<string, string> {
  for (const root of treeCandidates()) {
    if (!fs.existsSync(root)) {
      continue;
    }
    const files: Record<string, string> = {};
    walk(root, root, files);

    const absent = REQUIRED.filter((rel) => !(rel in files));
    if (absent.length > 0) {
      console.warn(`Paracore: ai/ tree at ${root} is incomplete — missing ${absent.join(", ")}`);
      continue;
    }
    return files;
  }

  console.warn(
    "Paracore: ai/ instruction tree not found. AI script generation may produce suboptimal code."
  );
  return {
    "copilot-instructions.md": `# Paracore — AI INSTRUCTIONS LOAD FAILURE

The \`ai/\` instruction tree was not found next to this extension.

The scaffolded \`.github/\` instructions will be INCOMPLETE. Regenerate the tree with
\`python paracore/scripts/gen-ai-workspace.py --write\` and confirm \`ai/\` is not excluded
by \`.vscodeignore\` when packaging.
`,
  };
}

/** {relative path under `.github/`: file text} — written verbatim by the scaffolder. */
export const WORKSPACE_AI_FILES: Record<string, string> = loadTree();
